+var gainBlindnessWaivers = map[string]string{ /* 6 entries, each a written reason */ }
+
+func TestEveryFragmentMatchDeclarationIsGainVisibleOrWaived(t *testing.T) {
+	paired := map[string]bool{}
+	for _, d := range Declarations {
+		if d.Mode == CountEqual { paired[d.Key] = true }
+	}
+	for _, d := range Declarations {
+		if d.Mode != FragmentMatch { continue }
+		if paired[d.Key+".value_count"] { continue }
+		reason, ok := gainBlindnessWaivers[d.Key]
+		if !ok { t.Errorf("%s is FragmentMatch with no paired count and no waiver", d.Key); continue }
+		if len(strings.TrimSpace(reason)) < 60 { t.Errorf("waiver for %s is too thin to be a reason", d.Key) }
+	}
+	for key := range gainBlindnessWaivers {
+		if !seen[key] { t.Errorf("waiver names %q, no longer a FragmentMatch declaration", key) }
+		if paired[key+".value_count"] { t.Errorf("%s has BOTH a waiver and a pairing", key) }
+	}
+	if len(seen) == 0 { t.Fatal("no FragmentMatch declarations examined — this guard is vacuous") }
+}
